mapper.update:
UPDATE pms_sku_stock sku
JOIN sms_flash_promotion promotion ON promotion.id = #{promotionId} AND promotion.status = 1
JOIN sms_flash_promotion_session session ON session.id = #{sessionId} AND session.status = 1
SET sku.lock_stock = GREATEST(COALESCE(sku.lock_stock, 0), 0) + #{quantity}
WHERE sku.id = #{skuId} AND sku.product_id = #{productId}
  AND #{quantity} > 0
  AND COALESCE(sku.stock, 0) - GREATEST(COALESCE(sku.lock_stock, 0), 0) >= #{quantity}

UPDATE pms_sku_stock
SET lock_stock = GREATEST(COALESCE(lock_stock, 0), 0) - #{quantity}
WHERE id = #{skuId} AND GREATEST(COALESCE(lock_stock, 0), 0) >= #{quantity}
